def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = 'aeiouAEIOU'
    result = []
    for char in message:
        if char in vowels:
            # Find the vowel and replace with letter 2 places ahead
            if char == 'a':
                result.append('c')
            elif char == 'e':
                result.append('g')
            elif char == 'i':
                result.append('k')
            elif char == 'o':
                result.append('q')
            elif char == 'u':
                result.append('w')
            elif char == 'A':
                result.append('C')
            elif char == 'E':
                result.append('G')
            elif char == 'I':
                result.append('K')
            elif char == 'O':
                result.append('Q')
            elif char == 'U':
                result.append('W')
        else:
            # Swap case
            if char.islower():
                result.append(char.upper())
            else:
                result.append(char.lower())
    return ''.join(result)
